--DS d_ds_address_customer
SELECT customer.customer_id,              customer.company_id,              customer.currency_id,              address.corp_address_id,              address.id,     customer.generate_statements_by,     customer.job_pricing FROM address    LEFT JOIN customer on customer.customer_id = address.id WHERE address.corp_address_id = '49889' AND customer.company_id = '1' GROUP BY customer.customer_id, customer.company_id, customer.currency_id, address.corp_address_id, address.id, customer.generate_statements_by,job_pricing ORDER BY customer.customer_id, customer.company_id, customer.currency_id, address.corp_address_id, address.id, customer.generate_statements_by,job_pricing